"use client";

import { useTranslations } from "next-intl";
import { useState } from "react";
import { Button } from "@/components/ui/button";

const POLL_MS = 1500;
const MAX_POLLS = 20;

/**
 * "Your angle": queues a personal angle (generated by an Inngest job, plan §6) and polls
 * until it is ready. Shows an error when generation is unavailable or the daily limit hit.
 */
export function AngleButton({ storyId }: { storyId: string }) {
  const t = useTranslations("radar.angle");
  const [state, setState] = useState<"idle" | "loading" | "error" | "limit">(
    "idle",
  );
  const [angle, setAngle] = useState<string | null>(null);

  async function request() {
    setState("loading");
    const res = await fetch(`/api/radar/${storyId}/angle`, { method: "POST" });
    if (res.status === 429) return setState("limit");
    if (!res.ok) return setState("error");
    const body = (await res.json()) as { angle?: string };
    if (body.angle) {
      setAngle(body.angle);
      return setState("idle");
    }
    for (let i = 0; i < MAX_POLLS; i++) {
      await new Promise((r) => setTimeout(r, POLL_MS));
      const poll = await fetch(`/api/radar/${storyId}/angle`);
      const data = (await poll.json()) as { angle?: string | null };
      if (data.angle) {
        setAngle(data.angle);
        return setState("idle");
      }
    }
    setState("error");
  }

  if (angle) {
    return (
      <p className="border-signal/30 bg-signal/5 rounded-md border p-3 text-sm">
        <span className="font-medium">{t("label")}</span> {angle}
      </p>
    );
  }
  return (
    <div className="flex items-center gap-2">
      <Button
        size="sm"
        variant="outline"
        onClick={request}
        disabled={state === "loading"}
      >
        {state === "loading" ? t("loading") : t("cta")}
      </Button>
      {state === "error" && (
        <span role="alert" className="text-danger text-xs">
          {t("error")}
        </span>
      )}
      {state === "limit" && (
        <span role="alert" className="text-danger text-xs">
          {t("limit")}
        </span>
      )}
    </div>
  );
}
